import asyncio, gel
def to_plain(obj):
    import decimal
    if obj is None:
        return None
    elif isinstance(obj, (int, float, str, bool)):
        return obj
    elif isinstance(obj, decimal.Decimal):
        return float(obj)
    elif isinstance(obj, list):
        return [to_plain(x) for x in obj]
    elif isinstance(obj, dict):
        return {k: to_plain(v) for k, v in obj.items()}
    elif hasattr(obj, '__dir__'):
        keys = obj.__dir__()
        res = {}
        for k in keys:
            if k.startswith('_'):
                continue
            val = getattr(obj, k)
            if callable(val):
                continue
            res[k] = to_plain(val)
        return res
    else:
        return obj

